  const [type, name] = item.trim().split(':');
  return { type, name };
});
const wantedType = selector.startsWith('#') ? 'id' : selector.startsWith('.') ? 'class' : 'tag';
const wantedName = selector.replace(/^[#.]/, '');
console.log(elements.filter(item => item.type === wantedType && item.name === wantedName).length);

