const fs = require('fs');
const [rawClasses, command] = fs.readFileSync(0, 'utf8').trim().split(/\r?\n/);
const classes = rawClasses.trim() ? rawClasses.trim().split(/\s+/) : [];
const [action, className] = command.trim().split(/\s+/);
const index = classes.indexOf(className);
if (action === 'add' && index === -1) classes.push(className);
if (action === 'remove' && index !== -1) classes.splice(index, 1);
if (action === 'toggle') {
  if (index === -1) classes.push(className);
  else classes.splice(index, 1);
}
console.log(classes.join(' '));

